export const DEFAULT_PM_RATE = 150;
export const DEFAULT_PM_PERCENT = 0.15;

export function createDefaultEstimationState(): EstimationState {
  return {
    locale: "en",
    standardWorkstreams: structuredClone(STANDARD_WORKSTREAM_TEMPLATES),
    thirdPartyIntegration: structuredClone(THIRD_PARTY_INTEGRATION_TEMPLATE),
    elixirSyncIntegration: structuredClone(ELIXIRSYNC_INTEGRATION_TEMPLATE),
    pmRate: DEFAULT_PM_RATE,
    pmPercent: DEFAULT_PM_PERCENT,
    hubspotLicense: createDefaultHubSpotLicenseState(),
  };
}

/**
 * Standard rate-card prices, keyed by workstream key (plus the two
 * integrations and "pm"). These stay fixed even when a specific
 * estimation's hourlyRate is overridden, so the UI can show "this
 * estimation deviates from the standard rate" next to the editable field.
 */
export const DEFAULT_HOURLY_RATES: Record<string, number> = {
  ...Object.fromEntries(STANDARD_WORKSTREAM_TEMPLATES.map((ws) => [ws.key, ws.hourlyRate])),
  third_party_integration: THIRD_PARTY_INTEGRATION_TEMPLATE.hourlyRate,
  elixirsync_integration: ELIXIRSYNC_INTEGRATION_TEMPLATE.hourlyRate,
  pm: DEFAULT_PM_RATE,
  // Dropped in the V3 workbook (trainings/go-live moved into each hub tab), but
  // estimations created before that still carry this workstream.
  deployment_golive: 135,
};
